# tebako VFS compatibility layer for lxml (xml2rfc payload).
#
# Why this exists: libxml2 2.13+ loads file-path sources through its
# fd-based input layer (xmlIO.c xmlInputFromFd), which dup(2)s the
# descriptor it was handed before reading. libtfs-preload (tebako v2.2.0)
# interposes open/read/lseek/close but NOT dup, so a memfs fd
# (TEBAKO_FD_FLAG, bit 30) fails dup with EBADF and every
# lxml.etree.{parse,ElementTree,RelaxNG,XMLSchema} of an in-image path
# dies with "Bad file descriptor" before any read.
#
# install() routes file-path loads through python's own IO instead
# (python's open/read ARE interposed, so VFS bytes flow):
#   1. path sources handed to etree.parse / etree.ElementTree become
#      binary streams (with base_url preserved so relative references
#      resolve);
#   2. RelaxNG / XMLSchema grammars are materialized — the grammar file
#      AND its transitive <include>/<externalRef> closure — to a host
#      temp dir and compiled from there, because libxml2 resolves schema
#      includes through its OWN global input callbacks (no lxml hook);
#      compiling the host copy makes libxml2 resolve the same relative
#      hrefs against the same directory layout with real fds;
#   3. a resolver on lxml's default parser answers file: URLs from
#      python streams (defense for entity/DTD loads on the default
#      parser).
# Remove once libtfs-preload interposes dup — see the feedstock README
# deviations section.
import io as _io
import os as _os
import tempfile as _tempfile

_installed = False
_grammar_dirs = {}

_RNG_NS = "http://relaxng.org/ns/structure/1.0"
_REF_TAGS = frozenset(
    ("{%s}include" % _RNG_NS, "{%s}externalRef" % _RNG_NS)
)


def _is_path(source):
    return isinstance(source, (str, bytes, _os.PathLike))


def install():
    global _installed
    if _installed:
        return
    from lxml import etree

    _orig_parse = etree.parse
    _orig_element_tree = etree.ElementTree

    def _path_text(source):
        return _os.fsdecode(source) if isinstance(source, bytes) else _os.fspath(source)

    def parse(source, *args, **kwargs):
        if _is_path(source):
            text = _path_text(source)
            if "://" not in text:
                kwargs.setdefault("base_url", text)
                source = open(source, "rb")
        return _orig_parse(source, *args, **kwargs)

    def _materialize_grammar(path):
        if path in _grammar_dirs:
            return _os.path.join(_grammar_dirs[path], _os.path.basename(path))
        root = _tempfile.mkdtemp(prefix="tebako-rng-")
        placed = {}

        def place(vfs_path):
            base = _os.path.basename(vfs_path)
            prior = placed.get(base)
            if prior is not None:
                if prior != vfs_path:
                    raise RuntimeError(
                        "tebako_lxml_vfs: grammar include basename collision: "
                        "%s vs %s" % (prior, vfs_path)
                    )
                return
            with open(vfs_path, "rb") as fh:
                data = fh.read()
            with open(_os.path.join(root, base), "wb") as out:
                out.write(data)
            placed[base] = vfs_path
            try:
                doc = _orig_parse(_io.BytesIO(data))
            except Exception:
                return
            for el in doc.getroot().iter():
                if el.tag not in _REF_TAGS:
                    continue
                href = el.get("href")
                if href and "://" not in href:
                    place(_os.path.join(_os.path.dirname(vfs_path), href))

        place(path)
        _grammar_dirs[path] = root
        return _os.path.join(root, _os.path.basename(path))

    def element_tree(element=None, file=None, parser=None):
        if file is not None and _is_path(file):
            return parse(_path_text(file), parser=parser)
        if _is_path(element):
            return parse(_path_text(element), parser=parser)
        return _orig_element_tree(element, file, parser)

    def _schema(orig):
        def wrapped(etree_=None, file=None):
            if file is not None and _is_path(file):
                text = _path_text(file)
                if "://" in text:
                    return orig(etree_, file)
                return orig(file=_materialize_grammar(text))
            if _is_path(etree_):
                return orig(parse(_path_text(etree_)))
            return orig(etree_, file)
        return wrapped

    class _VfsResolver(etree.Resolver):
        def resolve(self, url, pubid, context):
            if not isinstance(url, str):
                return None
            if url.startswith("file://"):
                from urllib.parse import unquote, urlparse
                path = unquote(urlparse(url).path)
            elif "://" in url:
                return None
            else:
                path = url
            try:
                stream = open(path, "rb")
            except OSError:
                return None
            return self.resolve_file(stream, context, base_url=url)

    etree.parse = parse
    etree.ElementTree = element_tree
    etree.RelaxNG = _schema(etree.RelaxNG)
    etree.XMLSchema = _schema(etree.XMLSchema)
    etree.get_default_parser().resolvers.add(_VfsResolver())
    _installed = True
